class BankAccount:
    def __init__(self, owner, balance):
        self.owner = owner
        self.balance = balance
        self.history = []
    def deposit(self, n):
        if n < 1:
            return False
        self.balance += n
        self.history.append(f"입금 {n}")
        return True
    def withdraw(self, n):
        if n < 1:
            return "금액 오류"
        if n > self.balance:
            self.history.append(f"출금 실패 {n}")
            return "잔액 부족"
