import math
class Fraction:
    def __init__(self, n, d):
        if d == 0:
            raise ZeroDivisionError
        if d < 0:
            n, d = -n, -d
        g = math.gcd(n, d)
        self.n = n // g
        self.d = d // g
    def __add__(self, o):
        return Fraction(self.n * o.d + o.n * self.d, self.d * o.d)
    def __sub__(self, o):
        return Fraction(self.n * o.d - o.n * self.d, self.d * o.d)
    def __mul__(self, o):
        return Fraction(self.n * o.n, self.d * o.d)
    def __eq__(self, o):
        return self.n == o.n and self.d == o.d
    def __lt__(self, o):
        return self.n * o.d < o.n * self.d
    def __str__(self):
        return str(self.n) if self.d == 1 else f"{self.n}/{self.d}"
k = int(input())
fs = []
for i in range(1, k + 1):
    n, d = map(int, input().split("/"))
    try:
        fs.append(Fraction(n, d))
    except ZeroDivisionError:
        print(f"[{i}번] 잘못된 분수")
if not fs:
    print("분수 없음")
else:
    print("정리:", *fs)
    total = fs[0]
    prod = fs[0]
    for f in fs[1:]:
        total = total + f
        prod = prod * f
    print("합:", total)
    print("곱:", prod)
    if len(fs) >= 2:
        print("첫째 - 둘째:", fs[0] - fs[1])
    print("정렬:", *sorted(fs))
    print("최대:", max(fs))
    print("최소:", min(fs))
    uniq = []
    for f in fs:
        if f not in uniq:
            uniq.append(f)
    print(f"서로 다른 값: {len(uniq)}개")

