class Duration:
    def __init__(self, m, s):
        total = max(0, m * 60 + s)
        self.m = total // 60
        self.s = total % 60
    def sec(self):
        return self.m * 60 + self.s
    def __add__(self, o):
        return Duration(0, self.sec() + o.sec())
    def __sub__(self, o):
        return Duration(0, self.sec() - o.sec())
    def __eq__(self, o):
        return self.sec() == o.sec()
    def __lt__(self, o):
        return self.sec() < o.sec()
    def __str__(self):
        return f"{self.m}:{self.s:02d}"
