class Member:
    def __init__(self, name):
        self.name = name
        self.__point = 0
    def get_point(self):
        return self.__point
    def rate(self):
        return 1
    def buy(self, price):
        p = price * self.rate() // 100
        self.__point += p
        return p
    def use(self, n):
        if 1 <= n <= self.__point:
            self.__point -= n
            return True
        return False
    def __str__(self):
        return f"{self.name} [일반] {self.__point}점"
class VipMember(Member):
    def __init__(self, name, level):
        super().__init__(name)
        self.level = level
    def rate(self):
        return 1 + self.level * 2
    def __str__(self):
        return super().__str__().replace("[일반]", f"[VIP{self.level}]")
n = int(input())
members = {}
for _ in range(n):
    p = input().split()
    if p[0] == "VIP":
        members[p[1]] = VipMember(p[1], int(p[2]))
    else:
        members[p[1]] = Member(p[1])
while True:
